import * as HttpServerResponse from "effect/http/HttpServerResponse";
import {
  CacheControl,
  type CacheControlName,
  edgeCacheControlHeader,
  PrivateCacheControl,
} from "../cache.ts";
import { mediaOrigin } from "../links.ts";
import type { ImageMode } from "./picture.tsx";
import type { Theme } from "./theme.ts";

const policy = (imgSrc: string) =>
  [
    "default-src 'none'",
    "style-src 'self'",
    "font-src 'self'",
    `img-src ${imgSrc}`,
    "base-uri 'none'",
    "form-action 'none'",
    "frame-ancestors 'none'",
  ].join("; ");

/**
 * How pages are sent. They run no scripts and load nothing from other
 * origins, and the Content-Security-Policy makes browsers hold them to it.
 * Photos come from this site as variants; only a Worker that can't make
 * them (see picture.tsx) links the originals on the media origin, and only
 * its pages may load images from there.
 */
export const contentSecurityPolicy: Readonly<Record<ImageMode, string>> = {
  variants: policy("'self'"),
  originals: policy(`'self' ${mediaOrigin}`),
};

/**
 * Each coding in an Accept-Encoding header with its weight (RFC 9110,
 * 12.5.3): `q` is read as a number, case-insensitively, and a coding
 * without a readable one weighs 1.
 */
function weights(acceptEncoding: string): Map<string, number> {
  const byCoding = new Map<string, number>();
  for (const part of acceptEncoding.split(",")) {
    const [coding = "", ...parameters] = part
      .split(";")
      .map((piece) => piece.trim());
    if (coding === "") continue;
    const q = parameters
      .map((parameter) => /^q\s*=\s*([0-9.]+)$/i.exec(parameter)?.[1])
      .find((value) => value !== undefined);
    const weight = q === undefined ? Number.NaN : Number(q);
    byCoding.set(coding.toLowerCase(), Number.isNaN(weight) ? 1 : weight);
  }
  return byCoding;
}

/**
 * The coding to send to a client that accepts `acceptEncoding`: Brotli,
 * else gzip, else `identity` (the HTML as is), or `undefined` when the
 * client refuses all three. A coding the client weighs 0 is refused, and
 * `*` stands for any coding it doesn't name. Identity is acceptable unless
 * refused that way (RFC 9110, 12.5.3), so a client that sends no
 * Accept-Encoding gets the HTML as is. Setting Content-Encoding is how a
 * Worker asks the runtime to compress a body.
 */
export function contentEncoding(
  acceptEncoding: string | undefined,
): "br" | "gzip" | "identity" | undefined {
  const accepted = weights(acceptEncoding ?? "");
  const wildcard = accepted.get("*");
  const weight = (coding: string) => accepted.get(coding) ?? wildcard;
  if ((weight("br") ?? 0) > 0) return "br";
  if ((weight("gzip") ?? 0) > 0) return "gzip";
  if ((weight("identity") ?? 1) > 0) return "identity";
  return undefined;
}

const headers = {
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-content-type-options": "nosniff",
  // Every page renders the mode its visitor's `theme` cookie fixes.
  vary: "accept-encoding, cookie",
} as const;

export interface HtmlOptions {
  /**
   * How long the page may be kept: a pure function of data or of the build.
   * Only the visitor's browser may keep a page in a mode they fixed.
   */
  readonly cacheControl: CacheControlName;
  /** The mode the page was rendered in, from the visitor's cookie. */
  readonly theme: Theme | undefined;
  /** How the page shows photos, which its policy allows. */
  readonly images: ImageMode;
  /** 200 unless said otherwise. */
  readonly status?: number;
  /**
   * How long reading its data took, in milliseconds, for Server-Timing.
   * Rendering is CPU alone, which workerd's clock doesn't count (it moves
   * only on I/O, against timing attacks), so it isn't reported.
   */
  readonly db?: number;
}

/**
 * A page's HTML, compressed when the client accepts it. A client that
 * refuses every coding we have, identity included, gets 406 Not Acceptable.
 */
export function htmlResponse(
  html: string,
  acceptEncoding: string | undefined,
  { cacheControl, theme, images, status = 200, db }: HtmlOptions,
): HttpServerResponse.HttpServerResponse {
  const encoding = contentEncoding(acceptEncoding);
  if (encoding === undefined) {
    return HttpServerResponse.text("Not Acceptable: br, gzip or identity", {
      status: 406,
      headers: {
        "cache-control": CacheControl.failure,
        vary: "accept-encoding",
      },
    });
  }
  return HttpServerResponse.text(html, {
    status,
    contentType: "text/html; charset=utf-8",
    headers: {
      ...headers,
      "content-security-policy": contentSecurityPolicy[images],
      "cache-control":
        theme === undefined
          ? CacheControl[cacheControl]
          : PrivateCacheControl[cacheControl],
      // The Worker's cache keeps a page in a fixed mode under that mode.
      ...(theme === undefined || cacheControl === "failure"
        ? {}
        : { [edgeCacheControlHeader]: CacheControl[cacheControl] }),
      ...(db === undefined
        ? {}
        : { "server-timing": `db;dur=${db.toFixed(1)}` }),
      ...(encoding === "identity" ? {} : { "content-encoding": encoding }),
    },
  });
}
